from pathlib import Path
import json
out=Path(__file__).resolve().parent
lines=['# Optimization round 3 — measured results','','100 performance is achievable on several pages, but this round does not establish 100 on every page or every run. The table records the final measured runs, including scores below 100.','','The real source files and php.ini were not overwritten. Install the 13 separate replacements in FILES.md after round 2; three are binary font files, the other ten are text replacements.','','## Final Lighthouse runs','','These are isolated preview results with gzip, optimized image copies and temporary PHP OPcache enabled. The PHP cache was warmed before each page pair. Each Lighthouse run starts a clean browser session.','','| Page | Mobile performance | Desktop performance | Mobile accessibility | Desktop accessibility |','| --- | ---: | ---: | ---: | ---: |']
for name,title in [('home','Home'),('about','About'),('blogs','Blogs'),('shop','Shop'),('contact','Contact'),('login','Login'),('favorites','Favourites')]:
 values=[];access=[]
 for device in ['mobile','desktop']:
  file=f'{name}-final-{device}.json';r=json.loads((out/file).read_text(encoding='utf-8-sig'))
  assert r['categories']['performance']['score'] is not None, file
  values.append(f"[{round(r['categories']['performance']['score']*100)}]({file})")
  access.append(str(round(r['categories']['accessibility']['score']*100)))
 lines.append(f"| {title} | {' | '.join(values+access)} |")
lines+=['','Best Practices scored 100 in these final runs. Public Home, About, Blogs, Shop and Contact SEO scored 100. Login and Favourites retain their intentional noindex policy; their lower SEO scores are expected and have not been changed to expose those pages.','','## Changes','','- Closed mega-menu links are inert, preventing keyboard focus inside hidden navigation. Opening the menu restores interaction.','- Icon-only About and Contact links now have accessible names. Login’s visible brand link is no longer hidden from assistive technology.','- Shop filter help text has stronger contrast.','- Storefront icon CSS is about 17 KB rather than about 100 KB. The three local subset fonts total about 23 KB instead of about 233 KB. The included Font Awesome licence must remain with the fonts.','- About, Blogs and Contact hero backgrounds are preloaded at the appropriate mobile/desktop width.','- Home newsletter animation pauses offscreen and respects reduced-motion preferences. Visible animation remains available.','','## Local server difference','','The actual port-8000 Contact baseline transferred about 170 KB of uncompressed HTML. The isolated preview compresses that response. Follow INSTALL.txt to check XAMPP compression and the previous OPcache guide, then measure your own server again. PHP supports automatic compression through its zlib.output_compression configuration; see the [official PHP documentation](https://www.php.net/manual/en/zlib.configuration.php). The real php.ini has not been edited.','','## Validation and remaining work','']
checks=json.loads((out/'browser-checks.json').read_text(encoding='utf-8-sig'))
failed=[x for x in checks['results'] if x['http']!=200 or not x['carouselWidthsPass'] or x.get('nextMoved') is False or x['horizontalOverflow'] or not x.get('closedMenuInert',True) or (x.get('mobileMenu') and (not x['mobileMenu']['visible'] or x['mobileMenu']['columns']!=4 or x['mobileMenu']['inert']))]
lines += [f"Responsive browser checks: {len(checks['results'])} page/width combinations, {len(failed)} failures and {len(checks['errors'])} JavaScript errors. See browser-checks.json.",'','Customer checks use the existing synthetic customer fixture and assess rendering, not real authenticated database latency. Other public pages have the earlier round-2 measurements; they were not all rebenchmarked after this shared layout update. Full live-domain PageSpeed Insights and authenticated production measurements remain to be checked.','','The final measured mobile performance gaps are mainly loading/rendering time and remaining main-thread work. A score of 100 is still a target on those pages. These changes do not guarantee every Google Ads, security, payment or SEO requirement simply because an automated category scores 100.','']
(out/'RESULTS.md').write_text('\n'.join(lines),encoding='utf-8')
print('Wrote results; responsive failures',len(failed),'errors',len(checks['errors']))
